// Speaking into a card.
//
// Press the mic, say the thing, press stop: the recording is saved, whisper is
// asked what it says, and the words are appended to the heading's own body
// with the audio linked from its `:AUDIO:` property. The Voice Notes tab does
// the same journey and files a *new* heading at the end of it; here the
// heading already exists and is what the card is about.
//
// The order matters and is the same one the voice notes take. The recording is
// saved the moment recording stops, before anything is attempted on it: a
// transcription fails in a dozen ways - whisper down, a model still loading, a
// take past the timeout - and none of them should cost the words that were
// said. If the transcription fails the audio is still there and still linked,
// and the message says so.

import * as React from 'react';
import Box from '@mui/joy/Box';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import Typography from '@mui/joy/Typography';
import CircularProgress from '@mui/joy/CircularProgress';

import MicIcon from '@mui/icons-material/Mic';
import StopCircleIcon from '@mui/icons-material/StopCircle';

import * as Db from '../db';
import { Card } from '../kanban';
import { pickMimeType, extFor, formatClock } from '../voice';
import { refreshBody } from './cardparts';

type Phase = 'idle' | 'asking' | 'recording' | 'working' | 'said';

export default function CardVoice({ card, onDone }: { card: Card; onDone: () => void }) {
    const [phase, setPhase] = React.useState<Phase>('idle');
    const [seconds, setSeconds] = React.useState(0);
    const [msg, setMsg] = React.useState('');

    const recorder = React.useRef<MediaRecorder | null>(null);
    const chunks = React.useRef<Blob[]>([]);
    const stream = React.useRef<MediaStream | null>(null);
    const started = React.useRef(0);
    const ticker = React.useRef<number | null>(null);
    const alive = React.useRef(true);

    React.useEffect(() => () => {
        alive.current = false;
        if (ticker.current !== null) window.clearInterval(ticker.current);
        if (stream.current) stream.current.getTracks().forEach(t => t.stop());
    }, []);

    const letGo = () => {
        if (ticker.current !== null) { window.clearInterval(ticker.current); ticker.current = null; }
        if (stream.current) { stream.current.getTracks().forEach(t => t.stop()); stream.current = null; }
        recorder.current = null;
    };

    const finish = async (blob: Blob, mime: string, took: number) => {
        setPhase('working');
        setMsg('Keeping the recording…');
        try {
            const name = `card.${extFor(mime)}`;
            const rec = await Db.ODb.saveVoiceRecording(blob, took, name);
            if (!rec || !rec.id) {
                setMsg('The recording could not be saved.');
                setPhase('idle');
                return;
            }

            setMsg('Asking whisper what it says…');
            let text = '';
            let model = '';
            try {
                const t = await Db.ODb.transcribeVoice(rec.id);
                text = ((t && t.text) || '').trim();
                model = (t && t.model) || '';
            } catch {
                text = '';
            }

            // Even with nothing to write, the audio is filed and linked: the
            // recording is the thing that cannot be made again.
            const res = await Db.ODb.appendVoiceNote({
                hash: card.Hash,
                text,
                id: rec.id,
                keepAudio: true,
                seconds: took,
                model,
            });
            if (!alive.current) return;
            if (!res || res.Ok === false) {
                setMsg((res && res.Msg) || 'The server did not take that.');
                setPhase('idle');
                return;
            }
            refreshBody(card.Hash);
            onDone();
            setMsg(text === ''
                ? 'Nothing came back from whisper — the recording is on the heading.'
                : 'Written onto this heading.');
            setPhase('said');
            window.setTimeout(() => { if (alive.current) { setPhase('idle'); setMsg(''); } }, 3000);
        } catch (e: any) {
            if (!alive.current) return;
            setMsg((e && e.message) || 'That did not go through.');
            setPhase('idle');
        }
    };

    const start = async () => {
        setMsg('');
        setPhase('asking');
        try {
            const media = await navigator.mediaDevices.getUserMedia({ audio: true });
            if (!alive.current) { media.getTracks().forEach(t => t.stop()); return; }
            stream.current = media;
            const mime = pickMimeType(t => !!(window as any).MediaRecorder && MediaRecorder.isTypeSupported(t));
            const rec = mime ? new MediaRecorder(media, { mimeType: mime }) : new MediaRecorder(media);
            chunks.current = [];
            rec.ondataavailable = e => { if (e.data && e.data.size > 0) chunks.current.push(e.data); };
            rec.onstop = () => {
                const took = (Date.now() - started.current) / 1000;
                const blob = new Blob(chunks.current, { type: rec.mimeType || mime || 'audio/webm' });
                letGo();
                if (blob.size === 0) {
                    setMsg('Nothing was recorded.');
                    setPhase('idle');
                    return;
                }
                finish(blob, rec.mimeType || mime || 'audio/webm', took);
            };
            recorder.current = rec;
            started.current = Date.now();
            setSeconds(0);
            rec.start();
            setPhase('recording');
            ticker.current = window.setInterval(() => {
                setSeconds((Date.now() - started.current) / 1000);
            }, 250);
        } catch {
            letGo();
            setMsg('This browser would not give up the microphone.');
            setPhase('idle');
        }
    };

    const stop = () => {
        const rec = recorder.current;
        if (!rec) { letGo(); setPhase('idle'); return; }
        try { rec.stop(); } catch { letGo(); setPhase('idle'); }
    };

    const busy = phase === 'working' || phase === 'asking';

    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }} onClick={e => e.stopPropagation()}>
            <Tooltip
                size="sm"
                placement="top"
                enterDelay={300}
                title={phase === 'recording'
                    ? 'Stop, transcribe, and write it onto this heading'
                    : 'Record a note. The words are added to this heading and the audio is kept and linked from it.'}
            >
                <span>
                    <IconButton
                        size="sm"
                        variant={phase === 'recording' ? 'soft' : 'plain'}
                        color={phase === 'recording' ? 'danger' : 'neutral'}
                        disabled={busy}
                        aria-label={phase === 'recording' ? 'Stop recording' : 'Record a note onto this heading'}
                        onClick={() => (phase === 'recording' ? stop() : start())}
                    >
                        {busy
                            ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '14px' }} />
                            : phase === 'recording'
                                ? <StopCircleIcon sx={{ fontSize: 14 }} />
                                : <MicIcon sx={{ fontSize: 14 }} />}
                    </IconButton>
                </span>
            </Tooltip>

            {phase === 'recording' && (
                <Typography
                    level="body-xs"
                    sx={{
                        fontSize: 10, fontFamily: 'monospace', color: 'danger.softColor',
                        // A dot that keeps time, so a recording left running is
                        // obviously still running.
                        '&::before': {
                            content: '""', display: 'inline-block', width: 6, height: 6,
                            borderRadius: '50%', background: 'currentColor', marginRight: '4px',
                            animation: 'cv-pulse 1.4s ease-in-out infinite',
                        },
                        '@keyframes cv-pulse': { '0%,100%': { opacity: 1 }, '50%': { opacity: 0.3 } },
                    }}
                >
                    {formatClock(seconds)}
                </Typography>
            )}

            {msg !== '' && phase !== 'recording' && (
                <Typography level="body-xs" sx={{ fontSize: 10, color: 'text.tertiary', minWidth: 0 }} noWrap title={msg}>
                    {msg}
                </Typography>
            )}
        </Box>
    );
}
