// Helpers for working with org tables in the spreadsheet editor.
//
// Org addresses cells as @row$col. Rows are counted from one and skip the
// horizontal rules, columns are counted from one straight across. Everything
// here speaks in both those org coordinates and in the raw indices of the row
// array the server hands us, so the two are always named apart.

import { TableRowData } from './db';

export const ADVANCED_MARKERS = ['!', '^', '_', '$', '/'];

export function isSep(row: TableRowData): boolean {
    return row.Kind === 'sep';
}

// Rows carrying a special marker in their first cell are org bookkeeping rows
// (column names, parameters, comments) and formulas never write to them.
export function isAdvanced(row: TableRowData): boolean {
    if (isSep(row) || row.Cells.length === 0) return false;
    return ADVANCED_MARKERS.indexOf((row.Cells[0] || '').trim()) >= 0;
}

// Raw row index -> org row number. Separator rows get 0, they have no number.
export function orgRowNumbers(rows: TableRowData[]): number[] {
    const out: number[] = [];
    let n = 0;
    for (const r of rows) {
        if (isSep(r)) {
            out.push(0);
        } else {
            n += 1;
            out.push(n);
        }
    }
    return out;
}

export function orgRowToRaw(rows: TableRowData[], orgRow: number): number {
    const nums = orgRowNumbers(rows);
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === orgRow) return i;
    }
    return -1;
}

export function rawToOrgRow(rows: TableRowData[], raw: number): number {
    const nums = orgRowNumbers(rows);
    return raw >= 0 && raw < nums.length ? nums[raw] : 0;
}

export function dataRowCount(rows: TableRowData[]): number {
    return rows.filter(r => !isSep(r)).length;
}

// A table whose second line is a rule reads its first line as a header, and a
// column formula leaves that header alone.
export function hasHeader(rows: TableRowData[]): boolean {
    return rows.length > 1 && isSep(rows[1]);
}

export function columnCount(rows: TableRowData[]): number {
    return rows.reduce((w, r) => Math.max(w, r.Cells.length), 0);
}

export function cellAt(rows: TableRowData[], r: number, c: number): string {
    if (r < 0 || r >= rows.length) return '';
    const cells = rows[r].Cells;
    return c >= 0 && c < cells.length ? cells[c] : '';
}

// The org label of a cell, e.g. "@3$2". Separator rows have no label.
export function cellRef(rows: TableRowData[], r: number, c: number): string {
    const row = rawToOrgRow(rows, r);
    if (row <= 0) return '';
    return `@${row}$${c + 1}`;
}

// One side of a formula target, in org coordinates. A null row or column
// stands for "every one of them", which is what a bare $2 or @3 means.
type Ref = { row: number | null; col: number | null };

// Resolve @2, $>, $total and friends. Offsets like >-1 count back from the end.
function resolveIndex(token: string, count: number, names: Record<string, number> | null): number | null {
    token = token.trim();
    if (token === '') return null;
    if (names && names[token] !== undefined) return names[token];
    let m = /^([<>])([<>]*)([+-]\d+)?$/.exec(token);
    if (m) {
        let base = m[1] === '<' ? 1 : count;
        if (m[3]) base += parseInt(m[3], 10);
        return Math.min(Math.max(base, 1), count);
    }
    m = /^\+?(\d+)$/.exec(token);
    if (m) return parseInt(m[1], 10);
    return null;
}

function parseRef(part: string, rowCount: number, colCount: number, names: Record<string, number> | null): Ref | null {
    part = part.trim();
    const m = /^(?:@([^$]+))?(?:\$(.+))?$/.exec(part);
    if (!m || (m[1] === undefined && m[2] === undefined)) return null;
    const row = m[1] === undefined ? null : resolveIndex(m[1], rowCount, null);
    const col = m[2] === undefined ? null : resolveIndex(m[2], colCount, names);
    if ((m[1] !== undefined && row === null) || (m[2] !== undefined && col === null)) return null;
    return { row, col };
}

// Which cells a formula target names, as raw row / zero based column pairs.
// Anything we cannot make sense of resolves to nothing rather than guessing.
export function resolveTarget(
    target: string,
    rows: TableRowData[],
    names: Record<string, number> | null,
): { r: number; c: number }[] {
    const cols = columnCount(rows);
    const dataRows = dataRowCount(rows);
    const parts = target.split('..');
    const start = parseRef(parts[0], dataRows, cols, names);
    if (!start) return [];
    const end = parts.length > 1 ? parseRef(parts[1], dataRows, cols, names) : start;
    if (!end) return [];

    const rowFrom = start.row === null ? 1 : Math.min(start.row, end.row === null ? start.row : end.row);
    const rowTo = start.row === null ? dataRows : Math.max(start.row, end.row === null ? start.row : end.row);
    const colFrom = start.col === null ? 1 : Math.min(start.col, end.col === null ? start.col : end.col);
    const colTo = start.col === null ? cols : Math.max(start.col, end.col === null ? start.col : end.col);

    // A column formula never writes the header line of the table.
    const skipHeader = start.row === null && hasHeader(rows);

    const out: { r: number; c: number }[] = [];
    for (let orgRow = rowFrom; orgRow <= rowTo; orgRow++) {
        if (skipHeader && orgRow === 1) continue;
        const raw = orgRowToRaw(rows, orgRow);
        if (raw < 0 || isAdvanced(rows[raw])) continue;
        for (let col = colFrom; col <= colTo; col++) {
            if (col < 1 || col > cols) continue;
            out.push({ r: raw, c: col - 1 });
        }
    }
    return out;
}

export type ParsedFormula = { raw: string; target: string; body: string };

export function parseFormula(formula: string): ParsedFormula | null {
    const idx = formula.indexOf('=');
    if (idx < 0) return null;
    return {
        raw: formula,
        target: formula.slice(0, idx).trim(),
        body: formula.slice(idx + 1).trim(),
    };
}

// Map every cell a formula writes to the formula that writes it. Later
// formulas win, which is the order org applies them in.
export function formulaTargets(
    formulas: string[],
    rows: TableRowData[],
    names: Record<string, number> | null,
): Record<string, string> {
    const out: Record<string, string> = {};
    for (const f of formulas) {
        const p = parseFormula(f);
        if (!p || p.body === '') continue;
        for (const t of resolveTarget(p.target, rows, names)) {
            out[`${t.r},${t.c}`] = f;
        }
    }
    return out;
}

// The formula that writes one cell, if any.
export function formulaForCell(
    formulas: string[],
    rows: TableRowData[],
    names: Record<string, number> | null,
    r: number,
    c: number,
): string | null {
    const map = formulaTargets(formulas, rows, names);
    const hit = map[`${r},${c}`];
    return hit === undefined ? null : hit;
}

// Point a formula at exactly one cell, replacing whatever formula already
// names that one cell on its own. An empty body removes it instead.
export function setCellFormula(
    formulas: string[],
    rows: TableRowData[],
    r: number,
    c: number,
    body: string,
): string[] {
    const ref = cellRef(rows, r, c);
    if (ref === '') return formulas;
    const out = formulas.filter(f => {
        const p = parseFormula(f);
        return !(p && p.target === ref);
    });
    if (body.trim() !== '') {
        out.push(`${ref}=${body.trim()}`);
    }
    return out;
}

// Formulas are written against org coordinates, so a formula that names a row
// or column by number no longer means what it did once rows move around. Warn
// rather than rewrite, the user knows what their formulas are for.
export function formulasAreStructural(formulas: string[]): boolean {
    return formulas.some(f => {
        const p = parseFormula(f);
        return p !== null && /[@$]\s*\d/.test(p.target);
    });
}

// Cells the user typed as numbers, for the selection summary.
export function toNumber(value: string): number | null {
    const v = value.trim().replace(/[$,]/g, '');
    if (v === '') return null;
    const n = Number(v);
    return isNaN(n) ? null : n;
}

export function tsvFromCells(cells: string[][]): string {
    return cells.map(row => row.join('\t')).join('\n');
}

export function cellsFromTsv(text: string): string[][] {
    const lines = text.replace(/\r\n/g, '\n').replace(/\n+$/, '').split('\n');
    return lines.map(l => l.split('\t'));
}

export function emptyRow(cols: number): TableRowData {
    return { Kind: 'data', Cells: new Array(cols).fill('') };
}

export function sepRow(cols: number): TableRowData {
    return { Kind: 'sep', Cells: new Array(cols).fill('') };
}

// Every row of a table has to be the same width.
export function normalize(rows: TableRowData[]): TableRowData[] {
    const cols = Math.max(1, columnCount(rows));
    return rows.map(r => {
        const cells = r.Cells.slice(0, cols);
        while (cells.length < cols) cells.push('');
        return { ...r, Cells: cells };
    });
}

// Column names declared by a "!" row, so formulas can say $total instead of $4.
export function columnNames(rows: TableRowData[]): Record<string, number> {
    const names: Record<string, number> = {};
    for (const row of rows) {
        if (isSep(row) || (row.Cells[0] || '').trim() !== '!') continue;
        for (let c = 1; c < row.Cells.length; c++) {
            const v = (row.Cells[c] || '').trim();
            if (v !== '') names[v] = c + 1;
        }
    }
    return names;
}

// ---------------------------------------------------------------------------
// The cells a formula reads.
//
// A formula body names its inputs the same way the target names its outputs,
// except that whatever it leaves out means "the cell being computed right now"
// - a column formula's $2 is the second column of the row it is writing. So a
// formula's sources are only meaningful one target cell at a time.

const ROW_TOKEN = String.raw`@(?:[<>]{1,2}(?:[-+]\d+)?|I{1,6}(?:[-+]\d+)?|[-+]?\d+)`;
const COL_TOKEN = String.raw`\$(?:[<>]{1,2}(?:[-+]\d+)?|[-+]?\d+|[A-Za-z_][A-Za-z0-9_]*)`;
const REF_TOKEN = `(?:${ROW_TOKEN}${COL_TOKEN}|${ROW_TOKEN}|${COL_TOKEN})`;
const RANGE_SRC = `(${REF_TOKEN})(?:\\.\\.(${REF_TOKEN}))?`;

function clampIndex(v: number, count: number): number {
    return Math.min(Math.max(v, 1), Math.max(count, 1));
}

// The data row an "@I" style rule reference lands on: the row after the nth
// rule when the reference opens a range, the row before it when it closes one.
function hlineDataRow(rows: TableRowData[], n: number, closing: boolean): number | null {
    const nums = orgRowNumbers(rows);
    let seen = 0;
    for (let i = 0; i < rows.length; i++) {
        if (!isSep(rows[i])) continue;
        seen += 1;
        if (seen !== n) continue;
        if (closing) {
            for (let j = i - 1; j >= 0; j--) if (!isSep(rows[j])) return nums[j];
            return null;
        }
        for (let j = i + 1; j < rows.length; j++) if (!isSep(rows[j])) return nums[j];
        return null;
    }
    return null;
}

type SourceCtx = { orgRow: number; col: number };

function sourceRow(token: string, rows: TableRowData[], ctx: SourceCtx, closing: boolean): number | null {
    const t = token.trim();
    const count = dataRowCount(rows);
    const m = /^(I{1,6})([-+]\d+)?$/.exec(t);
    if (m) {
        const base = hlineDataRow(rows, m[1].length, closing);
        if (base === null) return null;
        return clampIndex(base + (m[2] ? parseInt(m[2], 10) : 0), count);
    }
    // In a body an explicit sign counts from the row being written, unlike a
    // target where it is just a number.
    if (/^[-+]\d+$/.test(t)) return clampIndex(ctx.orgRow + parseInt(t, 10), count);
    return resolveIndex(t, count, null);
}

function sourceCol(token: string, cols: number, names: Record<string, number> | null, ctx: SourceCtx): number | null {
    const t = token.trim();
    if (/^[-+]\d+$/.test(t)) return clampIndex(ctx.col + parseInt(t, 10), cols);
    return resolveIndex(t, cols, names);
}

function parseSourceRef(
    part: string,
    rows: TableRowData[],
    names: Record<string, number> | null,
    ctx: SourceCtx,
    closing: boolean,
): { row: number; col: number } | null {
    const m = /^(?:@([^$]+))?(?:\$(.+))?$/.exec(part.trim());
    if (!m) return null;
    const row = m[1] === undefined ? ctx.orgRow : sourceRow(m[1], rows, ctx, closing);
    const col = m[2] === undefined ? ctx.col : sourceCol(m[2], columnCount(rows), names, ctx);
    if (row === null || col === null) return null;
    return { row, col };
}

// Which cells feed the formula when it computes the cell at (r, c), as raw row
// / zero based column pairs. References we cannot make sense of are left out
// rather than guessed at, the same way resolveTarget leaves them out.
export function formulaSources(
    formula: string,
    rows: TableRowData[],
    names: Record<string, number> | null,
    r: number,
    c: number,
): { r: number; c: number }[] {
    const p = parseFormula(formula);
    if (!p || p.body === '') return [];
    const orgRow = rawToOrgRow(rows, r);
    if (orgRow <= 0) return [];
    const ctx: SourceCtx = { orgRow, col: c + 1 };
    // Quoted text names nothing, and a remote() argument names cells in some
    // other table entirely.
    const body = p.body.replace(/"[^"]*"/g, ' ').replace(/remote\s*\([^)]*\)/g, ' ');

    const out: { r: number; c: number }[] = [];
    const seen: Record<string, boolean> = {};
    const re = new RegExp(RANGE_SRC, 'g');
    let m: RegExpExecArray | null;
    while ((m = re.exec(body)) !== null) {
        const a = parseSourceRef(m[1], rows, names, ctx, false);
        if (!a) continue;
        const b = m[2] !== undefined ? parseSourceRef(m[2], rows, names, ctx, true) : a;
        if (!b) continue;
        for (let row = Math.min(a.row, b.row); row <= Math.max(a.row, b.row); row++) {
            const raw = orgRowToRaw(rows, row);
            if (raw < 0) continue;
            for (let col = Math.min(a.col, b.col); col <= Math.max(a.col, b.col); col++) {
                if (col < 1 || col > columnCount(rows)) continue;
                const key = `${raw},${col - 1}`;
                if (seen[key]) continue;
                seen[key] = true;
                out.push({ r: raw, c: col - 1 });
            }
        }
    }
    return out;
}

// Every other cell the same formula writes, so the editor can show the reach
// of the formula behind the selected cell.
export function formulaPeers(
    formula: string,
    rows: TableRowData[],
    names: Record<string, number> | null,
    r: number,
    c: number,
): { r: number; c: number }[] {
    const p = parseFormula(formula);
    if (!p) return [];
    return resolveTarget(p.target, rows, names).filter(t => !(t.r === r && t.c === c));
}
