// Org's column view, on the client.
//
// The server does all the reading and all the arithmetic - which properties a
// `#+COLUMNS:` line names, what each heading holds, and what a parent's total
// comes to. What is left here is what a *table* needs and a server cannot know:
// which rows are folded away, which column is being sorted on, and whether a
// cell may be typed into.
//
// The one rule worth stating: **a cell's own value is not what the cell shows.**
// On a leaf they are the same. On a parent that rolls up they are not, and an
// editor opened on the shown value would write a project's total effort onto the
// project heading the first time anybody pressed return in it.

export type ColumnSpec = {
    Property: string;
    Title: string;
    Width: number;
    Summary: string;
    // "property" | "todo" | "item" | "tags" | "priority" | "derived"
    Kind: string;
    // "duration" | "number" | ""
    Numbers: string;
    Allowed: string[] | null;
};

export type ColumnCell = {
    Value: string;
    Own: string;
    Summed: boolean;
    Number: number;
};

export type ColumnRow = {
    Hash: string;
    Headline: string;
    Level: number;
    LineNum: number;
    Status: string;
    Priority: string;
    Tags: string[] | null;
    HasChildren: boolean;
    Cells: ColumnCell[];
};

export type ColumnsResult = {
    Ok: boolean;
    Msg: string;
    File: string;
    Columns: string;
    From: string;
    Spec: ColumnSpec[] | null;
    Rows: ColumnRow[] | null;
};

// Can this column be typed into, and through which endpoint?
//
// Kept here rather than as a list of property names, because the server already
// decided and a second opinion in the browser is a second thing to keep in step.
export function isEditable(spec: ColumnSpec): boolean {
    return spec.Kind === 'property' || spec.Kind === 'todo' || spec.Kind === 'item';
}

// What to put in the editor when a cell is opened.
//
// The heading's *own* value, never the rollup. A project showing 31:45 summed
// from its tasks has no effort of its own, and offering 31:45 as the current
// value is offering to write it.
export function editValue(cell: ColumnCell): string {
    return cell.Own || '';
}

// Which rows are hidden because an ancestor is folded.
//
// Folding is by hash and the outline is a flat list with levels, so a row is
// hidden when any row above it that is folded has a smaller level and nothing in
// between has climbed back out. Walking a stack of levels is what makes that one
// pass rather than a lookup per ancestor.
export function hiddenRows(rows: ColumnRow[], folded: Set<string>): Set<string> {
    const hidden = new Set<string>();
    // The levels of the folded ancestors currently in force.
    const shut: number[] = [];
    for (const r of rows) {
        while (shut.length > 0 && r.Level <= shut[shut.length - 1]) shut.pop();
        if (shut.length > 0) {
            hidden.add(r.Hash);
            // A row that is already hidden cannot also be a fold point anybody
            // can see, but its children are hidden by the ancestor either way -
            // so it is not pushed, and the ancestor keeps hiding them.
            continue;
        }
        if (r.HasChildren && folded.has(r.Hash)) shut.push(r.Level);
    }
    return hidden;
}

// Every hash in the list that has something under it, for "fold all".
export function foldableRows(rows: ColumnRow[]): string[] {
    return rows.filter(r => r.HasChildren).map(r => r.Hash);
}

// The rows of one heading's subtree, itself included - what a fold hides and
// what "sum of this branch" is about.
export function subtreeOf(rows: ColumnRow[], hash: string): ColumnRow[] {
    const at = rows.findIndex(r => r.Hash === hash);
    if (at < 0) return [];
    const out = [rows[at]];
    for (let i = at + 1; i < rows.length && rows[i].Level > rows[at].Level; i++) out.push(rows[i]);
    return out;
}

// Sorting a column, without breaking the outline.
//
// A column view is an outline, and sorting it as a flat list would move children
// away from their parents and turn the indentation into a lie. So siblings are
// sorted **within their parent** and the tree is walked back out in order - which
// is what org does when it sorts a subtree, and the only sort that leaves the
// indentation meaning what it says.
export function sortWithinParents(
    rows: ColumnRow[], column: number, dir: 'asc' | 'desc', numeric: boolean,
): ColumnRow[] {
    if (rows.length === 0) return rows;

    type Node = { row: ColumnRow; kids: Node[] };
    const roots: Node[] = [];
    const stack: Node[] = [];
    for (const row of rows) {
        const node: Node = { row, kids: [] };
        while (stack.length > 0 && stack[stack.length - 1].row.Level >= row.Level) stack.pop();
        if (stack.length === 0) roots.push(node);
        else stack[stack.length - 1].kids.push(node);
        stack.push(node);
    }

    const sign = dir === 'asc' ? 1 : -1;
    const cmp = (a: Node, b: Node): number => {
        const ca = a.row.Cells[column];
        const cb = b.row.Cells[column];
        if (!ca || !cb) return 0;
        // An empty cell sorts last whichever way round the column is, because
        // "nothing here" is not a small value - it is an absence, and burying
        // the filled-in rows under a block of blanks is never what was wanted.
        const ea = numeric ? ca.Value === '' : ca.Value.trim() === '';
        const eb = numeric ? cb.Value === '' : cb.Value.trim() === '';
        if (ea !== eb) return ea ? 1 : -1;
        if (ea && eb) return 0;
        if (numeric) return sign * (ca.Number - cb.Number);
        return sign * ca.Value.localeCompare(cb.Value, undefined, { sensitivity: 'base' });
    };

    const out: ColumnRow[] = [];
    const walk = (ns: Node[]) => {
        const sorted = [...ns].sort(cmp);
        for (const n of sorted) {
            out.push(n.row);
            walk(n.kids);
        }
    };
    walk(roots);
    return out;
}

// How wide to draw a column, from the `%25` the spec may carry.
//
// A width is a request rather than a rule: org writes one to stop a long item
// pushing everything else off the screen, and a table that can scroll has less
// need of it than a fixed-width buffer does. So it becomes a maximum, and a
// column with no width gets whatever it needs.
export function columnWidth(spec: ColumnSpec): number | undefined {
    if (!spec.Width || spec.Width <= 0) return undefined;
    // Roughly a character, for a table drawn in the interface font rather than
    // in a terminal. Exactness is not the point: not being pushed off the
    // screen is.
    return spec.Width * 8;
}
